class Solution {
    fun closestRoom(rooms:Array<IntArray>,queries:Array<IntArray>):IntArray{
        rooms.sortByDescending{
            it[1]
        };
        val order=queries.indices.sortedByDescending{
            queries[it][1]
        };
        val ids=java.util.TreeSet<Int>();
        val answer=IntArray(queries.size){
            -1
        };
        var room=0;
        for(index in order){
            while(room<rooms.size&&rooms[room][1]>=queries[index][1])ids.add(rooms[room++][0]);
            if(ids.isEmpty())continue;
            val preferred=queries[index][0];
            val low=ids.floor(preferred);
            val high=ids.ceiling(preferred);
            answer[index]=when{
                low==null->high;
                high==null->low;
                preferred-low<=high-preferred->low;
                else->high
            }
        };
        return answer
    }
}

